// Keep visible exploration covers and full project videos playing by default.
(()=>{const seen=new WeakSet();const start=v=>{v.muted=true;v.defaultMuted=true;v.autoplay=true;v.loop=true;v.playsInline=true;if(!v.getAttribute('src')&&(v.dataset.src||v.dataset.video))v.src=v.dataset.src||v.dataset.video;v.play().catch(()=>{})};const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){start(x.target);io.unobserve(x.target)}}),{rootMargin:'300px'});const scan=()=>document.querySelectorAll('video').forEach(v=>{if(!seen.has(v)){seen.add(v);io.observe(v)}});new MutationObserver(scan).observe(document.body,{childList:true,subtree:true});scan();document.addEventListener('visibilitychange',()=>{if(!document.hidden)document.querySelectorAll('video').forEach(v=>{if(v.currentSrc)v.play().catch(()=>{})})});})();
